<?php
namespace xdecaro\Component\Organizations\Administrator\Table;
defined('_JEXEC') or die;use Joomla\CMS\Table\Table;use Joomla\Database\DatabaseDriver;
final class OrganizationTable extends Table{public function __construct(DatabaseDriver $db){parent::__construct('#__xdecaroorganizations_organizations','id',$db);}public function check():bool{$this->name=trim((string)$this->name);if($this->name===''){$this->setError('Organization name is required.');return false;}foreach(['legal_name','code','vat_id','tax_identifier','email','pec_email','phone','website','address_line','postal_code','city','region','language','logo','notes'] as $f){if(property_exists($this,$f)&&$this->{$f}!==null){$v=trim((string)$this->{$f});$this->{$f}=$v!==''?$v:null;}}if(property_exists($this,'country_code')&&$this->country_code!==null){$v=strtoupper(trim((string)$this->country_code));$this->country_code=$v!==''?$v:null;}$this->parent_id=!empty($this->parent_id)?(int)$this->parent_id:null;return parent::check();}}
